from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2

    def test_add_and_get(self, repo):
        task = Task(id=1, title="Hello")
        repo.add(task)
        assert repo.get(1) is task

    def test_add_duplicate_raises(self, repo):
        task = Task(id=1, title="Hello")
        repo.add(task)
        with pytest.raises(ValueError, match="already exists"):
            repo.add(Task(id=1, title="Dup"))

    def test_get_nonexistent_returns_none(self, repo):
        assert repo.get(999) is None

    def test_list_returns_all(self, repo):
        repo.add(Task(id=1, title="A"))
        repo.add(Task(id=2, title="B"))
        assert len(list(repo.list())) == 2

    def test_update_existing(self, repo):
        task = Task(id=1, title="Old")
        repo.add(task)
        task.title = "New"
        repo.update(task)
        assert repo.get(1).title == "New"

    def test_update_nonexistent_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(Task(id=999, title="Missing"))

    def test_delete_existing_returns_true(self, repo):
        repo.add(Task(id=1, title="X"))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_nonexistent_returns_false(self, repo):
        assert repo.delete(999) is False


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("python"), Tag("Python"), Tag("PYTHON")])
        assert len(result) == 1
        assert result[0].name == "python"

    def test_converts_strings(self):
        result = normalize_tags(["Flask", "django"])
        assert all(isinstance(t, Tag) for t in result)
        assert [t.name for t in result] == ["flask", "django"]

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["b", "a", "b", "c"])
        assert [t.name for t in result] == ["b", "a", "c"]

    def test_empty_iterable(self):
        assert normalize_tags([]) == []
